const { chromium } = require('playwright-core');
const fs = require('fs');
const path = require('path');
const chrome=process.env.CHROME_BIN, url=process.env.QA_URL||'http://127.0.0.1:4173/en.html';
const out=process.env.SCREENSHOT_DIR||'docs/site-evolution/connected-system-r1/review-r131';
const productSha=process.env.PRODUCT_SHA||'2183da3471eeedeea9500ba721294a7f590248ff';
const viewports=[[1440,900,'1440x900'],[1366,768,'1366x768'],[1280,800,'1280x800'],[1200,800,'1200x800']];
const failures=[]; const report={productSha,generatedAt:new Date().toISOString(),desktop:{},mobile:{},failures};
fs.mkdirSync(out,{recursive:true});
const check=(v,l,d='')=>{if(!v)failures.push(d?`${l}: ${d}`:l)};
async function openPage(browser,w,h){const context=await browser.newContext({viewport:{width:w,height:h},reducedMotion:'no-preference'});const page=await context.newPage();await page.goto(url,{waitUntil:'domcontentloaded',timeout:60000});await page.waitForSelector('[data-connected-system]',{timeout:20000});await page.waitForFunction(()=>document.querySelectorAll('[data-system-stage]').length===4,null,{timeout:10000,polling:50});await page.waitForTimeout(900);await page.evaluate(()=>{const e=document.querySelector('[data-connected-system]'),y=e.getBoundingClientRect().top+scrollY;scrollTo({top:Math.max(0,y-34),behavior:'instant'})});await page.waitForTimeout(120);return{context,page}}
async function armRecorder(page){await page.evaluate(()=>{window.__r131Seen=[];window.__r131Obs?.disconnect?.();const s=[...document.querySelectorAll('[data-system-stage]')];const rec=()=>s.forEach((n,i)=>{if(n.classList.contains('is-active')&&!window.__r131Seen.includes(i))window.__r131Seen.push(i)});window.__r131Obs=new MutationObserver(rec);s.forEach(n=>window.__r131Obs.observe(n,{attributes:true,attributeFilter:['class']}));rec()})}
async function replayToResponse(page){await armRecorder(page);const seen=page.evaluate(()=>new Promise((resolve,reject)=>{const s=[...document.querySelectorAll('[data-system-stage]')];let done=false;const inspect=()=>{if(done)return;const active=s.filter(n=>n.classList.contains('is-active'));if(active.length===1&&s[2].classList.contains('is-active')){done=true;obs.disconnect();clearTimeout(timer);resolve(s.map(n=>[...n.classList]))}};const obs=new MutationObserver(inspect);s.forEach(n=>obs.observe(n,{attributes:true,attributeFilter:['class']}));const timer=setTimeout(()=>{done=true;obs.disconnect();reject(new Error('RESPONSE active not observed'))},5200);inspect()}));await page.locator('[data-replay-system]').evaluate(el=>el.click());return seen}
async function waitBalanced(page){await page.waitForFunction(()=>{const s=[...document.querySelectorAll('[data-system-stage]')];return s.length===4&&s.every(n=>n.classList.contains('is-balanced'))},null,{timeout:6500,polling:50})}
async function metrics(page){return page.evaluate(()=>{const r=e=>{const b=e.getBoundingClientRect();return{left:b.left,right:b.right,top:b.top,bottom:b.bottom,width:b.width,height:b.height}};const q=s=>document.querySelector(s),section=q('[data-connected-system]'),shell=q('.cs-shell'),field=q('.cs-system-field'),rail=q('.cs-spine'),carriage=q('.cs-light-carriage'),stages=[...document.querySelectorAll('[data-system-stage]')];return{viewport:{width:innerWidth,height:innerHeight},scrollWidth:document.documentElement.scrollWidth,section:r(section),shell:r(shell),field:r(field),rail:r(rail),carriage:r(carriage),hero:r(q('#hero')),heroBg:getComputedStyle(q('#hero')).backgroundColor,sectionBg:getComputedStyle(section).backgroundColor,stages:stages.map(s=>({box:r(s),joint:r(s.querySelector('.cs-transfer-joint')),name:r(s.querySelector('.cs-stage-name')),copy:r(s.querySelector('.cs-stage-copy')),components:r(s.querySelector('.cs-components')),classes:[...s.classList]})),activeCount:stages.filter(s=>s.classList.contains('is-active')).length}})}
function validate(m,key){const{viewport,scrollWidth,shell,field,rail,carriage,stages}=m;check(scrollWidth<=viewport.width+1,`${key}-overflow`,`${scrollWidth}>${viewport.width}`);check(shell.left>=-1&&shell.right<=viewport.width+1,`${key}-shell-bounds`);check(rail.left>=field.left-2&&rail.right<=field.right+2,`${key}-rail-bounds`);check(carriage.left>=field.left-110&&carriage.right<=field.right+110,`${key}-carriage-x`);check(carriage.top>=field.top-120&&carriage.bottom<=field.bottom+120,`${key}-carriage-y`);stages.forEach((s,i)=>{for(const[n,b]of[['name',s.name],['copy',s.copy],['components',s.components]]){check(b.left>=-1&&b.right<=viewport.width+1,`${key}-stage${i+1}-${n}-x`);check(b.bottom<=viewport.height+3,`${key}-stage${i+1}-${n}-bottom`,`${b.bottom.toFixed(1)}>${viewport.height}`)}const jc=(s.joint.top+s.joint.bottom)/2,rc=(rail.top+rail.bottom)/2;check(Math.abs(jc-rc)<=7,`${key}-stage${i+1}-joint-rail`,`${jc.toFixed(1)} vs ${rc.toFixed(1)}`)})}
async function hoverQA(page,key){for(const i of[0,2,1,3]){const st=page.locator('[data-system-stage]').nth(i);await st.hover({position:{x:50,y:130}});try{await page.waitForFunction(x=>{const s=[...document.querySelectorAll('[data-system-stage]')];return s.filter(n=>n.classList.contains('is-active')).length===1&&s[x].classList.contains('is-active')},i,{timeout:1800,polling:50})}catch(_){failures.push(`${key}-hover-${i+1}`)}check(await page.locator('[data-system-stage].is-active').count()===1,`${key}-hover-${i+1}-single`);const m=await metrics(page);check(m.carriage.left>=m.field.left-110&&m.carriage.right<=m.field.right+110,`${key}-hover-${i+1}-carriage`)}await page.mouse.move(5,5);await page.waitForTimeout(400)}
async function desktop(browser,w,h,key){console.log(`render ${key}`);const{context,page}=await openPage(browser,w,h);const classesAtActivation=await replayToResponse(page);await page.waitForTimeout(35);const response=await metrics(page);validate(response,`${key}-response`);check(response.activeCount===1,`${key}-one-active`,String(response.activeCount));check(response.stages[0].classes.includes('is-settled'),`${key}-trust-settled`,JSON.stringify(response.stages[0].classes));check(response.stages[1].classes.includes('is-settled'),`${key}-inquiry-settled`,JSON.stringify(response.stages[1].classes));check(response.stages[2].classes.includes('is-active'),`${key}-response-active`,JSON.stringify(response.stages[2].classes));check(response.stages[3].classes.includes('is-future'),`${key}-result-future`,JSON.stringify(response.stages[3].classes));await page.screenshot({path:path.join(out,`en-${key}-response-active.png`),fullPage:false});await waitBalanced(page);const sequenceSeen=await page.evaluate(()=>window.__r131Seen||[]);check([0,1,2,3].every((n,i)=>sequenceSeen[i]===n),`${key}-sequence`,JSON.stringify(sequenceSeen));const balanced=await metrics(page);validate(balanced,`${key}-balanced`);check(balanced.stages.every(s=>s.classes.includes('is-balanced')),`${key}-all-balanced`);if(key==='1440x900'||key==='1200x800')await page.screenshot({path:path.join(out,`en-${key}-final-balanced.png`),fullPage:false});await hoverQA(page,key);const item={classesAtActivation,response,balanced,sequenceSeen};if(key==='1440x900'||key==='1366x768'){const gap=Math.round((response.section.top-response.hero.bottom)*100)/100;check(Math.abs(gap)<=1,`${key}-hero-gap`,String(gap));check(response.heroBg===response.sectionBg,`${key}-hero-bg`,`${response.heroBg} vs ${response.sectionBg}`);item.continuity={gap,heroBg:response.heroBg,sectionBg:response.sectionBg}}report.desktop[key]=item;console.log(`captured ${key} ${JSON.stringify(sequenceSeen)}`);await context.close()}
async function mobile(browser,w,h,key){const{context,page}=await openPage(browser,w,h),st=page.locator('[data-system-stage]').nth(2);await st.evaluate(el=>{const r=el.getBoundingClientRect();scrollTo({top:scrollY+r.top+r.height/2-innerHeight*.565,behavior:'instant'})});await page.waitForTimeout(750);const active=await st.evaluate(el=>el.classList.contains('is-active'));await page.evaluate(()=>scrollBy(0,90));await page.waitForTimeout(180);const hidden=await page.locator('[data-site-header]').evaluate(el=>el.classList.contains('header-hidden'));await page.evaluate(()=>scrollBy(0,-100));await page.waitForTimeout(180);const shown=!(await page.locator('[data-site-header]').evaluate(el=>el.classList.contains('header-hidden'))),overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1);check(active,`${key}-active`);check(hidden,`${key}-hide`);check(shown,`${key}-show`);check(!overflow,`${key}-overflow`);report.mobile[key]={active,hidden,shown,overflow};await context.close()}
(async()=>{if(!chrome)throw new Error('CHROME_BIN required');const browser=await chromium.launch({executablePath:chrome,headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{for(const[w,h,k]of viewports)await desktop(browser,w,h,k);await mobile(browser,390,844,'390x844');await mobile(browser,844,390,'844x390')}finally{await browser.close()}fs.writeFileSync(path.join(out,'qa-report.json'),JSON.stringify(report,null,2));if(failures.length){console.error(failures.join('\n'));process.exit(1)}console.log('R1.3.1 REAL DESKTOP QA PASS')})().catch(e=>{try{fs.writeFileSync(path.join(out,'qa-report.json'),JSON.stringify(report,null,2))}catch(_){}console.error(e);process.exit(1)});
